        for c in range(w):
            if grid[r][c] != 2 or not threes:
                continue
            # Markers on the object act at their own location. Markers just
            # outside an object project onto its nearest cell.
            dist, (ar, ac) = min(
                (abs(r - x) + abs(c - y), (x, y)) for x, y in threes
            )
            if dist > 2:
                continue
            for i in range(max(0, ar - 1), min(h, ar + 2)):
                for j in range(max(0, ac - 1), min(w, ac + 2)):
                    if grid[i][j] == 3:
                        out[i][j] = 1
    return out
